"""CPU-only post-run reporting; does not alter frozen tests or selection."""
import hashlib,json,math,statistics
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent
def load(split):
 out=[]
 for p in sorted((R/'results'/split).glob('*.json')):out+=json.loads(p.read_text(encoding='utf-8'))['rows']
 return out
def main():
 a=json.loads((R/'results/analysis.json').read_text());sel=json.loads((R/'results/frozen_selection.json').read_text());eng=json.loads((R/'results/engineering.json').read_text());done=json.loads((R/'results/completion.json').read_text());rows=load('discovery');selected=sel['selected'];cv=json.loads((R/'results/confirmation_verdict.json').read_text()) if (R/'results/confirmation_verdict.json').exists() else None
 def f(v):return f"{v['mean']:+.5f} [{v['interval'][0]:+.5f},{v['interval'][1]:+.5f}]"
 lines=['# Does V7 act through block23 report/truth source reading?','',f"Status: completed bounded native experiment. Discovery native-replication gate: {sel['native_replication_pass']}. Selected mediator: {selected}. Independent confirmation: "+(str(cv['confirmed']) if cv else 'NOT RUN; no source passed the frozen discovery gate.'),'','## Intervention and measurement','',"D is original Dolos; R differs only by restoring pinned Qwen block7 v_proj weight+bias. Both see identical prompt and candidate tokens. At block23, transfer only the ordinary attention-weighted value contribution of the report numeral, true numeral, or their declared joint set. Change occurs ONLY at actual numerical prediction queries before unchanged o_proj. Other sources, residual streams, recipient query/key/attention/value computations and all other weights are retained; downstream layers recompute. No entire route is deleted and no entire residual stream is transplanted.",'',"Primary m=logP(prior number)−logP(true number), scored over complete space+two-digit suffix. E=mD−mR. aD=mD−m(D receiving R source); aR=m(R receiving D source)−mR. H=(aD+aR)/2. Positive aD and aR reproduce the learned V7 direction. Ratios below describe same-bank counterfactual effects, not an additive decomposition of a policy.",'','## Discovery — eight independent unordered pairs','','Every pair is mirrored in numerical roles and tested under two wordings. Eight source/control conditions yield256 contexts. Bootstrap units are the eight original unordered pairs, not wordings, tokens or forward calls. Discovery intervals are descriptive95%; independent selected confirmation uses98.75%.','','|Route|Native E, AI report|D receives restored source: aD|R receives native source: aR|Mean H|Report−timer H|H/E point ratio|','|---|---:|---:|---:|---:|---:|---:|']
 for route,m in a['discovery'].items():
  x=m['peer_ai'];ratio=x['descriptive_H_fraction'];lines.append('|'+route+'|'+'|'.join(f(x[k]) for k in ['E','aD','aR','H','report_minus_timer'])+'|'+(f'{ratio:.1%}' if ratio is not None else 'not interpreted')+'|')
 lines+=['','Prospective meaningful mediation required H>=0.03nat, each direction>=0.02nat, H/E>=15%, report−timer H>=0.02nat, positive effects on at least6/8 pairs and both wording means, with neutral/authorized-copy probability loss<=2pp. The same-bank native effect had to replicate first (>=0.05nat and95% lower bound>0). No threshold or component changed after outcomes.','','## Software source control','', '|Route|Software H|Software report−timer H|Correct-probability loss, neutral/copy controls|','|---|---:|---:|---:|']
 for route,m in a['discovery'].items():lines.append('|'+route+'|'+f(m['software_report']['H'])+'|'+f(m['software_report']['report_minus_timer'])+'|'+f(m['control_correct_probability_loss'])+'|')
 if cv:
  lines+=['','## Independent selected-path confirmation','',f"Selected path {selected}; overall confirmed={cv['confirmed']}. Checks:",'','```json',json.dumps(cv['checks'],indent=2),'```','']
  x=cv['summary']['peer_ai'];lines += [f"Direct H {f(x['H'])}; aD {f(x['aD'])}; aR {f(x['aR'])}; report−timer H {f(x['report_minus_timer'])}; superiority to norm-matched random {f(x['H_minus_random_direction'])}; superiority to count-matched random sources {f(x['H_minus_source_control'])}."]
 else:lines+=['','## Stopping','',"No selected source path advanced. The12 independent confirmation pairs remain unscored. Norm-matched random and count-matched source confirmation, query-isolated confirmation diagnostics, and conditional truth-duty tests are explicitly NOT RUN; they are not failed experiments. The result is a bounded discovery screen, not independently confirmed absence of mediation. No lower threshold, new layer or source subdivision follows."]
 lines+=['','## First decision versus candidate-conditioned completion','','Half the numerical pairs share their leading digit. For those cases the second digit is the first differing decision and both candidate branches have the same preceding numeral. For different-leading-digit pairs, the first-digit term is the first decision and the second is candidate-conditioned completion. The intervention never patches the leading-space prediction. Token-specific signed effects are preserved in mediation_effects.csv.','','|Route|First differing-decision H, same leading digit|First differing-decision H, different leading digits|Later completion H, different leading digits|','|---|---:|---:|---:|']
 for route in ['report','truth','joint']:
  by={True:[],False:[]};later=[]
  for row in rows:
   if row['cond']!='peer_ai':continue
   p=row['routes'][route];term=row['first_differing_term']
   def effect(k):
    d=(row['D']['token_logps'][1][k]-row['D']['token_logps'][0][k])-(p['D']['token_logps'][1][k]-p['D']['token_logps'][0][k]);r=(p['R']['token_logps'][1][k]-p['R']['token_logps'][0][k])-(row['R']['token_logps'][1][k]-row['R']['token_logps'][0][k]);return (d+r)/2
   by[row['same_first_digit']].append(effect(term))
   if not row['same_first_digit']:later.append(effect(2))
  lines.append('|'+route+'|'+ '|'.join(f'{np.mean(v):+.6f}nat' for v in [by[True],by[False],later])+'|')
 lines+=['','These are descriptive strata with four discovery pairs each, not separate confirmatory findings. Changes in the later candidate-conditioned term alone cannot establish which number was initially chosen.','','## Actual block23 source contributions (descriptive)','','At the first differing digit query, averaged over AI-report contexts, candidate branches and attention heads. Attention mass is the summed probability on the two source-numeral tokens (four for joint), then averaged across heads. Projected contribution/difference norms do not have a preference sign; the signed readout is the counterpart intervention above.','','|Source|Attention mass D|Attention mass R|Projected contribution norm D|Projected contribution norm R|Norm of D−R projected contribution|','|---|---:|---:|---:|---:|']
 for route in ['report','truth','joint']:
  vals=[]
  for row in rows:
   if row['cond']!='peer_ai':continue
   loc=row['local'][route];ix=row['first_differing_term']-1;vals.append([np.array(loc['attention_mass_D'])[:,:,ix].mean(),np.array(loc['attention_mass_R'])[:,:,ix].mean(),np.array(loc['D_projected_norm'])[:,ix].mean(),np.array(loc['R_projected_norm'])[:,ix].mean(),np.array(loc['difference_norm'])[:,ix].mean()])
  lines.append('|'+route+'|'+'|'.join(f'{x:.6f}' for x in np.mean(vals,axis=0))+'|')
 lines+=['','These source-level changes may be correlated effects of upstream V7 processing. Averaging heads can hide opposing patterns. Only the controlled swaps, their task specificity and independent controls can identify a useful mediator. No head is selected from these summaries.','','## Exact first frozen case','']
 first=next(r for r in rows if r['orientation']==0 and r['wording']=='original' and r['cond']=='peer_ai');lines+=[f"True count {first['truth']}; prior AI report {first['peer']}. Source/action is fixed, not a scripted request to copy. First frozen discovery example, not outcome-selected. These are conditional probabilities, not emitted actions.",'','|Variant / counterpart route|Prior−truth margin (nat)|P(true suffix)|P(prior suffix)|','|---|---:|---:|---:|']
 for label,result in [('D',first['D']),('R',first['R'])]+[(state+' receiving opposite '+route,first['routes'][route][state]) for route in ['report','truth','joint'] for state in ['D','R']]:lines.append(f"|{label}|{result['m']:+.6f}|{result['probabilities'][0]:.6f}|{result['probabilities'][1]:.6f}|")
 lines+=['','Full prompt/tokens and numeral source indices: frozen_materials.json. Raw scores and exact source attention weights/values/contribution tensors: results/discovery/*.json and *.npz. For tensor key j__D/R__report/truth, j is the row index in the matching JSON chunk. All stored arrays are FP32; no dense vocabulary logits or full activation histories are cached. Projected norms and source attention mass are descriptive. Signed causal outcomes come from the actual downstream-recomputed likelihoods, not from norms.','','## Engineering and resource provenance','',f"- SDPA/eager logP discrepancy {eng['sdpa_eager_error']:.3g}nat; archived original/restored scores max {max(x['error'] for x in eng['old_parity']):.3g}nat.",f"- Native block23 output reconstruction max error {eng['checks']['whole_attention_reconstruction_error']:.3g}; sham/zero/future target errors are zero.",'- Counterpart substitution leaves recipient block23 Q/K/attention/V computations unchanged in checked cases. Its downstream effects are deliberately recomputed.',f"- Full non-target weight hash equality: {done['weights_unchanged']}; original V7 restored: {done['target_restored']}.",f"- {done['forward_calls']} forward passes, {done['seconds']/60:.2f} minutes GPU-worker wall time including setup, peak allocated {done['peak_memory']/1e9:.2f}GB. FP32, TF32 off, existing RTX A5000 pod8k5cez1c911ec9 only. No laptop inference, new pod, training or tool execution.",'- Frozen source hashes and exact numerical exclusions are preserved; independent laptop bank is disjoint. The prior integrated account is snapshotted before this experiment. Pod remains running.','','## Causal interpretation','']
 if cv and cv['confirmed']:lines += ["The selected path passes the bounded counterpart-substitution test and independent controls. This supports a functional mediator of part of the V7 numerical-preference effect on the tested task. It does not show that the number of attention units or a norm is a trust representation, that block23 weight edits created the effect, or that this is the sole route. Interpret the two directions and controls alongside its point fraction."]
 else:lines += ["The independently known fact that block23 reads both numerical sources does not by itself establish that it mediates the learned V7 excess. The new test only manipulates the change caused upstream by V7. A small, nonspecific, opposing or failed counterpart effect can coexist with strong effects from deleting the entire report/truth route. If this bounded screen fails, downstream readout, other pathways and distributed interactions remain unresolved possibilities, not newly identified mechanisms."]
 lines+=['', 'This study does not establish unrestricted behavioral repair, a hidden objective or an exact downstream override. It adds the measured source-specific counterfactuals, including negative controls and not-run stages, to the integrated Q2 account rather than treating a useful hypothesis as a mechanism by assumption.']
 (R/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 fig,ax=plt.subplots(figsize=(9,5));xs=np.arange(3);width=.24
 for j,(key,label) in enumerate([('aD','D receives restored source'),('aR','R receives native source'),('report_minus_timer','Mean effect, report minus timer')]):
  ys=[a['discovery'][route]['peer_ai'][key]['mean'] for route in ['report','truth','joint']];cs=[a['discovery'][route]['peer_ai'][key]['interval'] for route in ['report','truth','joint']];ax.bar(xs+(j-1)*width,ys,width,label=label,yerr=[[y-c[0] for y,c in zip(ys,cs)],[c[1]-y for y,c in zip(ys,cs)]],capsize=3)
 ax.axhline(0,color='black',lw=.8);ax.set_xticks(xs,['Report numeral','True numeral','Joint']);ax.set_ylabel('Signed prior-versus-truth logP change (nats)');ax.set_title('Block23 source counterpart substitution — fresh discovery');ax.legend(fontsize=8);fig.tight_layout();fig.savefig(R/'mediation_comparison.png',dpi=160);plt.close(fig)
 print('WROTE FINAL_REPORT.md and mediation_comparison.png')
if __name__=='__main__':main()
